      pm1: [0.7, 0.82, 0.86, 'premolar'], pm2: [0.67, 0.78, 0.86, 'premolar'], m1: [1.02, 0.72, 1.04, 'molar'], m2: [0.93, 0.68, 1.0, 'molar'],    
